with exploded as (select id, customer_id, coupon_codes, inline(items) from carts) select id, coupon_codes, product_id, price, percent_rank() over (partition by customer_id order by qty desc nulls last) qty_percent_rank, dense_rank() over w_running qty_dense_rank, rank() over (order by price desc nulls last) price_rank, round(product_id / sum(product_id) over (partition by promo, customer_id), 4) product_id_share from exploded window w_running as (partition by customer_id order by qty nulls first);
